def dividir_seguro(a, b):
    try:
        res = a / b
    except ZeroDivisionError:
        return "Error: no puedes dividir entre cero"
    except TypeError:
        return "Error: los argumentos deben ser números"
    else:
        return f"Éxito: {res}"
    finally:
        # Limpieza o log garantizado
        pass

print(dividir_seguro(10, 2))
print(dividir_seguro(10, 0))

